import * as dntShim from "../../_dnt.shims.js";
import { INVALID_ARGUMENT } from "../../src/errors/index.js";
import { cliLogger, exitProcess } from "../utils/index.js";
import { createSuccessEnvelope, isJsonMode, outputJson } from "../shared/json-output.js";
export async function readJsonFile(path, label) {
    let content;
    try {
        content = await dntShim.Deno.readTextFile(path);
    }
    catch (error) {
        // Only a missing file is a usage mistake; permission or I/O failures on an
        // existing file are runtime errors and must keep exit code 1.
        if (!(error instanceof dntShim.Deno.errors.NotFound))
            throw error;
        throw INVALID_ARGUMENT.create({ detail: `Invalid ${label}: ${error.message}`, cause: error });
    }
    try {
        return JSON.parse(content);
    }
    catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw INVALID_ARGUMENT.create({ detail: `Invalid ${label}: ${message}`, cause: error });
    }
}
export async function outputTriggerList(input) {
    if (isJsonMode()) {
        await outputJson(createSuccessEnvelope(input.command, {
            items: input.items,
            errors: input.errors,
        }));
        if (input.errors.length > 0)
            exitProcess(1);
        return;
    }
    if (input.items.length === 0) {
        cliLogger.info(`No ${input.command} found.`);
    }
    else {
        for (const item of input.items) {
            cliLogger.info(input.formatItem(item));
        }
    }
    if (input.errors.length > 0) {
        cliLogger.error("");
        cliLogger.error(`${input.errors.length} ${input.command} file failed to load:`);
        for (const error of input.errors) {
            cliLogger.error(`  - ${error.sourcePath}: ${error.message}`);
        }
        exitProcess(1);
    }
}
export async function outputTriggerRun(input) {
    if (isJsonMode()) {
        await outputJson(createSuccessEnvelope(input.command, input));
        return;
    }
    cliLogger.info(`${input.command} "${input.triggerId}" ran ${input.target.kind} "${input.target.id}" in ${input.durationMs}ms`);
    if (input.output !== undefined) {
        cliLogger.info(JSON.stringify(input.output, null, 2));
    }
}
